cd opt; python -c "
import numpy as np
L=open('xtbopt.xyz').read().split('\n')[2:143]
el=[l.split()[0] for l in L];P=np.array([[float(x) for x in l.split()[1:]] for l in L])
for i,e in enumerate(el):
  d=np.linalg.norm(P-P[i],axis=1)
  if e in('Ir','Zn'): print(e,[(el[j],j,round(d[j],2)) for j in np.argsort(d)[1:10]])
for i in range(135,141):
  d=np.linalg.norm(P-P[i],axis=1); print(i,[(el[j],j,round(d[j],2)) for j in np.argsort(d)[1:3]])
"
